// Convert JSON string into an object if necessary
if (typeof msg.payload === "string") {
    try {
        msg.payload = JSON.parse(msg.payload);
    } catch (err) {
        node.error("Invalid JSON in BME280 payload", msg);
        return null;
    }
}

// Validate payload
if (!msg.payload ||
    typeof msg.payload !== "object" ||
    Array.isArray(msg.payload)) {
    node.error("BME280 payload must be a JSON object", msg);
    return null;
}

// Assign message topic
msg.topic = "bme";

return msg;

// Receives BME280 data or OpenWeatherMap response.
const now = Date.now();
let state = flow.get("dryingState") || {};

// ==========================================
// 1. RECEIVE AND VALIDATE INPUT DATA
// ==========================================

if (msg.topic === "bme") {
    const p = msg.payload || {};

    const t = Number(p.temperature);
    const h = Number(p.humidity);
    const pressure = Number(p.pressure);

    if (![t, h, pressure].every(Number.isFinite) ||
        h < 0 || h > 100) {
        node.warn("Invalid BME280 payload.");
        return null;
    }

    state.bme = {
        temperature: t,
        humidity: h,
        pressure: pressure,
        updatedAt: now
    };

} else if (msg.topic === "weather") {
    const p = msg.payload || {};

    if (!p.main ||
        !Number.isFinite(Number(p.main.temp)) ||
        !Number.isFinite(Number(p.main.humidity)) ||
        !Number.isFinite(Number(p.main.pressure))) {
        node.warn("Invalid OpenWeatherMap response.");
        return null;
    }

    state.weather = {
        temperature: Number(p.main.temp),
        humidity: Number(p.main.humidity),
        pressure: Number(p.main.pressure),

        description:
            (p.weather && p.weather[0] &&
                p.weather[0].description) || "Unavailable",

        rainMmPerHour: Number(
            (p.rain && (p.rain["1h"] || p.rain["3h"])) || 0
        ),

        windSpeed: Number(
            (p.wind && p.wind.speed) || 0
        ),

        updatedAt: now
    };
}

flow.set("dryingState", state);

// Wait until both data sources are available.
if (!state.bme || !state.weather) {
    return null;
}


// ==========================================
// 2. ENVIRONMENTAL DATA FUSION
// ==========================================

// BME280: 80%
// Chennai Weather: 20%

const raw = {
    temperature:
        0.8 * state.bme.temperature +
        0.2 * state.weather.temperature,

    humidity:
        0.8 * state.bme.humidity +
        0.2 * state.weather.humidity,

    pressure:
        0.8 * state.bme.pressure +
        0.2 * state.weather.pressure
};


// ==========================================
// 3. EMA FILTERING
// ==========================================

// Alpha = 1.0 for independent test-case evaluation.
// Change to 0.8 when using live sensor readings.

const alpha = 1.0;

let prev = flow.get("dryingFiltered");

const filtered = prev ? {
    temperature:
        alpha * raw.temperature +
        (1 - alpha) * prev.temperature,

    humidity:
        alpha * raw.humidity +
        (1 - alpha) * prev.humidity,

    pressure:
        alpha * raw.pressure +
        (1 - alpha) * prev.pressure

} : raw;

flow.set("dryingFiltered", filtered);


// ==========================================
// 4. VAPOUR PRESSURE DEFICIT (VPD)
// ==========================================

const T = filtered.temperature;

const RH = Math.max(
    0,
    Math.min(100, filtered.humidity)
);

// Saturation Vapour Pressure
const svp =
    0.6108 * Math.exp(
        (17.27 * T) / (T + 237.3)
    );

// Actual Vapour Pressure
const avp = svp * RH / 100;

// Vapour Pressure Deficit
const vpd = Math.max(0, svp - avp);


// ==========================================
// 5. DRYING INDEX
// ==========================================

const dryingIndex = Math.max(
    0.15,
    Math.min(
        1.8,
        Math.pow(vpd / 1.7, 1.15)
    )
);


// ==========================================
// 6. SUITABILITY SCORE
// ==========================================

const clamp = (x, min, max) =>
    Math.max(min, Math.min(max, x));

// Temperature score
const tempScore = clamp(
    ((T - 15) / 20) * 100,
    0, 100
);

// Humidity score
const humidityScore = clamp(
    ((90 - RH) / 60) * 100,
    0, 100
);

// VPD score
const vpdScore = clamp(
    (vpd / 1.5) * 100,
    0, 100
);

// Weighted suitability score
const suitabilityScore = Math.round(
    0.4 * tempScore +
    0.5 * humidityScore +
    0.1 * vpdScore
);


// ==========================================
// 7. DRYING SUITABILITY RECOMMENDATION
// ==========================================

let suitability =
    suitabilityScore >= 75 ? "Suitable" :
        suitabilityScore >= 45 ? "Partially Suitable" :
            "Not Suitable";

// Rain detection
const rainingNow =
    state.weather.rainMmPerHour > 0;

if (rainingNow) {
    suitability = "Not Suitable";
}

const advice = rainingNow
    ? "Rain is currently reported in Chennai. Avoid outdoor drying."
    : suitability === "Suitable"
        ? "Conditions are favourable. Choose a well-ventilated drying location."
        : suitability === "Partially Suitable"
            ? "Drying is possible but may take longer. Improve airflow and keep clothes sheltered."
            : "Conditions are unfavourable. Prefer indoor drying with good ventilation.";


// ==========================================
// 8. FABRIC-SPECIFIC DRYING ESTIMATION
// ==========================================

const times = {
    cotton: 6 / dryingIndex,
    polyester: 2.5 / dryingIndex,
    nylon: 2 / dryingIndex
};

const fabricAdvice = {};

for (const [fabric, hours] of Object.entries(times)) {

    fabricAdvice[fabric] = {
        hours: Number(hours.toFixed(2)),

        recommendation:
            hours < 3 ? "Excellent" :
                hours <= 6 ? "Suitable" :
                    hours <= 10 ? "Partially Suitable" :
                        "Not Recommended"
    };
}


// ==========================================
// 9. DASHBOARD OUTPUT
// ==========================================

msg.payload = {

    bme: state.bme,

    chennai: state.weather,

    combined: {
        temperature: Number(T.toFixed(2)),
        humidity: Number(RH.toFixed(2)),
        pressure: Number(filtered.pressure.toFixed(2))
    },

    analysis: {
        svp: Number(svp.toFixed(3)),
        avp: Number(avp.toFixed(3)),
        vpd: Number(vpd.toFixed(3)),
        dryingIndex: Number(dryingIndex.toFixed(3)),

        suitabilityScore,
        suitability,
        advice,
        rainingNow
    },

    fabrics: fabricAdvice,

    updatedAt: new Date().toISOString()
};

return msg;

// Add your OpenWeatherMap API key below. Keep it private.
const API_KEY = "API_KEY";
msg.method = "GET";
msg.url = `https://api.openweathermap.org/data/2.5/weather?lat=13.0827&lon=80.2707&units=metric&appid=${API_KEY}`;
return msg;
